    74  //TODO is this safe for multithreading?
    75  static pcg32_random_t UA_rng = PCG32_INITIALIZER;
    76
    77  void
    78  UA_random_seed(u64 seed) {
    79      pcg32_srandom_r(&UA_rng, seed, (u64)UA_DateTime_now());
    80  }
    81
    82  u32
    83  UA_UInt32_random(void) {
    84      return (u32)pcg32_random_r(&UA_rng);
    85  }
