    94  UA_String
    95  UA_String_fromChars(char const src[]) {
    96      UA_String str;
    97      str.length = strlen(src);
    98      if(str.length > 0) {
    99          str.data = (u8*)UA_malloc(str.length);
   100          if(!str.data)
   101              return UA_STRING_NULL;
   102          memcpy(str.data, src, str.length);
   103      } else {
   104          str.data = (u8*)UA_EMPTY_ARRAY_SENTINEL;
   105      }
   106      return str;
   107  }
   108
   109  UA_Boolean
   110  UA_String_equal(const UA_String *s1, const UA_String *s2) {
   111      if(s1->length != s2->length)
   112          return false;
   113      i32 is = memcmp((char const*)s1->data,
   114                      (char const*)s2->data, s1->length);
   115      return (is == 0) ? true : false;
   116  }
