   118  static UA_StatusCode
   119  String_copy(UA_String const *src, UA_String *dst, const UA_DataType *_) {
   120      UA_StatusCode retval = UA_Array_copy(src->data, src->length, (void**)&dst->data,
   121                                           &UA_TYPES[UA_TYPES_BYTE]);
   122      if(retval == UA_STATUSCODE_GOOD)
   123          dst->length = src->length;
   124      return retval;
   125  }
   126
   127  static void
   128  String_clear(UA_String *s, const UA_DataType *_) {
   129      UA_Array_delete(s->data, s->length, &UA_TYPES[UA_TYPES_BYTE]);
   130  }
